from format_lecon import Lesson,paras,steps,table,ABBR,D
from html import escape
ABBR.update({'OCT':'tomographie par cohérence optique','UD':'unidose','CYP3A4':'enzyme 3A4 du cytochrome P450','H1':'récepteur histaminique de type 1'})
texts={n:(D/'evidence'/f'{n}_frais.txt').read_text().splitlines() for n in ['dexafree','atropine']}
def q(n,start):
 a=list(dict.fromkeys(s for s in texts[n] if s.startswith(start)));assert len(a)==1,(n,start,len(a))
 return '<blockquote><p>« '+escape(a[0].removeprefix('·'))+' »</p></blockquote>'
def d(s):return q('dexafree',s)
def a(s):return q('atropine',s)
l=Lesson('Uvéite antérieure',7)
dex=l.subwindow('dexafree','Unidose (UD) : Dexafree 0,1 %',paras('Dexafree UD 0,1 % est un collyre en unidose, Swissmedic 57477. La notice indique 1,1 mg/ml de phosphate sodique de dexaméthasone. Il ne s’agit ni d’une injection ni d’un implant intraoculaire.',
'La prescription suppose un examen ophtalmologique et un diagnostic. Ce choix documentaire ne constitue pas une recommandation de ce produit pour toute uvéite. Les infections, la cornée, la pression et les contre-indications doivent être évaluées.')+
'<h3>Indication et posologie de la notice</h3>'+d('Collyre 0,1%:')+d('Inflammations non infectieuses')+d('La dexaméthasone ne devrait')+d('Instiller, dans le cul')+d('Dans les cas sévères,')+d('La durée du traitement')+paras('La réduction dépend de l’examen, pas uniquement de la disparition de la douleur. Cette notice ne permet pas d’affirmer qu’un traitement prolongé au-delà de 14 jours serait automatiquement couvert. Une uvéite persistante nécessite une nouvelle décision spécialisée et la documentation du cadre de prescription.')+
'<h3>Contre-indications</h3>'+d("Hypersensibilité à l'un")+d('Infections oculaires non traitées')+d('·les affections bactériennes')+d('·les infections fongiques')+d('·les kératites superficielles')+d('Tuberculose,')+d('Glaucome,')+d('Ne pas utiliser de stéroïde')+
'<h3>Examen, infection et surveillance</h3>'+d('Ne pas administrer aux nouveau-nés')+d('Ne prescrire le Dexafree')+d('Le patient doit être examiné')+d("En présence d'une maladie provoquant")+d('Ce médicament contient 80 microgrammes')+d("Les patients souffrant d'infection oculaire")+d('Le traitement oculaire topique')+d("Les patients ayant souffert d'épisodes herpétiques")+d('La pression intraoculaire, le glaucome secondaire')+paras('La rubrique Contre-indications mentionne le glaucome. Les formulations de précaution ailleurs dans la notice ne doivent pas être transformées en autorisation générale de traitement d’un patient glaucomateux. Les situations infectieuses demandent un traitement causal efficace et une décision spécialisée.')+
'<h3>Âge et interactions</h3>'+d('Les sujets âgés et les enfants')+paras('L’enzyme 3A4 du cytochrome P450 (CYP3A4) intervient dans le métabolisme de nombreux médicaments. Les inhibiteurs cités ci-dessous peuvent accroître les effets systémiques du corticoïde.')+d('Un syndrome de Cushing')+d('Des inhibiteurs du CYP3A4')+d('En cas de traitement concomitant par un autre collyre,')+d("Lors de l'utilisation concomitante avec un mydriatique,")+
'<h3>Grossesse et allaitement</h3>'+d("Chez l'être humain, les données")+d('En conséquence, ce médicament')+d('Le passage de la dexaméthasone')+
'<h3>Utilisation de l’unidose</h3>'+d('Conserver les unidoses dans le sachet,')+d("Jeter l'unidose après utilisation.")+paras('Une baisse visuelle nouvelle pendant le traitement doit être réévaluée. Elle n’est pas automatiquement un signe d’inflammation insuffisamment traitée : pression, cristallin, infection ou autre effet indésirable doivent être considérés.'),(60,))
atr=l.subwindow('atropine','Dose unitaire (SDU) : Atropine 0,5 % Faure',paras('Atropine SDU Faure contient du sulfate d’atropine à 5 mg/ml, soit 0,5 %, en dose unitaire. Le numéro Swissmedic est 46994. La clé documentaire 46994035 ne remplace pas ce numéro. Cette présentation oculaire ne doit pas être confondue avec une solution injectable.',
'La dilatation de la pupille et le blocage temporaire de l’accommodation, appelé cycloplégie, ont des indications précises. Le traitement peut notamment viser les adhérences entre iris et cristallin, appelées synéchies postérieures. Il ne remplace pas le traitement de la cause de l’uvéite.')+
'<h3>Indication et dose</h3>'+a('Collyre dans des doses unitaires')+a('Pour prévenir et rompre les synéchies')+a('Instiller 1 goutte 1 à 3 fois')+
'<h3>Contre-indications</h3>'+a('Glaucome et glaucome à angle étroit.')+a("Hypersensibilité à l'atropine")+
'<h3>Enfant, terrain et absorption</h3>'+a('Les enfants et les petits enfants seront traités')+a("L'atropine doit être utilisée avec prudence")+a('A tenir hors de portée des enfants')+a('Pour réduire au minimum les effets systémiques,')+paras('L’occlusion du canal lacrymal réduit le passage systémique mais ne supprime pas le risque de toxicité. La prudence pédiatrique de cette notice n’annule pas l’interdiction du corticoïde documenté ici avant 2 ans.')+
'<h3>Interactions</h3>'+paras('Dans la citation suivante, H1 désigne le récepteur histaminique de type 1.')+a("L'effet de l'atropine peut être renforcé")+
'<h3>Grossesse et allaitement</h3>'+a('Des malformations (hernie inguinale, pied bot)')+a("Interrompre l'allaitement si un traitement")+paras('Cette consigne d’allaitement diffère de celle du Dexafree. Elle doit être expliquée dans le projet thérapeutique avec le prescripteur. Une affirmation générale sur tous les collyres serait incorrecte.')+
'<h3>Conduite, intoxication et conservation</h3>'+a('Les patients doivent être rendus attentifs au fait que, pendant le traitement')+a('Rougeur de la face, accélération du pouls,')+a('Une fois le blister ouvert,')+a('La pointe de la pipette ne doit entrer')+paras('Les effets sur la pupille et l’accommodation peuvent persister après la dernière dose. Prévoir un transport sûr et respecter l’interdiction de conduite de la notice. Une ingestion accidentelle impose une aide médicale immédiate.'),(61,))
l.add('L’{uvéite antérieure} est une inflammation située principalement dans la partie avant de l’œil. Elle concerne l’iris et parfois le corps ciliaire. Sa reconnaissance ne suffit pas : la cause et les complications orientent le traitement.',paras('Le terme iritis désigne l’atteinte de l’iris ; iridocyclite associe le corps ciliaire. L’examen à la lampe à fente recherche notamment des cellules inflammatoires dans la chambre antérieure. Une rougeur superficielle seule ne démontre pas cette inflammation.',
'Les formes intermédiaires, postérieures et les panuvéites ont une autre étendue anatomique. Le fond d’œil aide à ne pas limiter à tort le diagnostic au segment antérieur. Le nom de la localisation ne désigne pas un agent infectieux ni une maladie générale particulière.'),(55,56,58))
l.add('Le {contexte clinique} peut être isolé, récidivant ou associé à une maladie générale. Des formes peu symptomatiques existent, notamment chez l’enfant. Aucune fréquence suisse comparable aux autres diagnostics du lot n’est établie ici.',paras('Une atteinte inflammatoire ne signifie pas nécessairement une infection. Inversement, une hypothèse immunitaire ne dispense pas de rechercher une infection lorsque le tableau l’évoque. Des épisodes antérieurs ne prouvent pas que le nouvel épisode a exactement la même cause.',
'Les sources citent notamment des associations avec spondyloarthrite, sarcoïdose, maladie de Behçet et arthrite idiopathique juvénile. Une partie des cas reste sans cause identifiée. Les proportions publiées varient selon les populations et ne sont pas transposées en classement suisse.'),(55,56,57,58))
l.add('Les {bases anatomiques} expliquent douleur, photophobie et complications. L’inflammation peut modifier la transparence des milieux et la circulation du liquide oculaire. Le retentissement visuel ne se mesure pas à la seule rougeur.',table(['Structure ou phénomène','Signification','Conséquence'],[
['Iris et corps ciliaire','Structures du segment antérieur impliquées dans l’inflammation.','Douleur, gêne à la lumière et troubles de l’accommodation possibles.'],
['Cellules en chambre antérieure','Éléments inflammatoires visibles à la lampe à fente.','Suivi objectif de l’activité au-delà des symptômes.'],
['Précipités rétrocornéens','Dépôts sur la face postérieure de la cornée.','Indices qui contribuent à caractériser le tableau.'],
['Synéchies postérieures','Adhérences de l’iris au cristallin.','Déformation pupillaire et possibles difficultés de circulation de l’humeur aqueuse.'],
['Macula, cristallin et pression','Une complication peut toucher d’autres fonctions de l’œil.','Œdème maculaire, cataracte ou hyperpression peuvent réduire la vision.']
]),(55,58,59,61))
l.add('Les {signes d’alarme} demandent un avis ophtalmologique urgent. Douleur, photophobie et baisse visuelle doivent faire dépasser l’hypothèse d’une simple conjonctivite. Un traitement corticoïde empirique avant examen peut masquer ou aggraver une infection.',paras('La stratégie des Hôpitaux universitaires de Genève (HUG) recommande de contacter l’ophtalmologue en urgence devant toute suspicion d’uvéite. Une douleur importante, une forte baisse ou une opacité cornéenne renforcent cette priorité. Sans lampe à fente, reconnaître les limites de l’examen plutôt que conclure à une forme bénigne.',
'Un niveau blanchâtre en chambre antérieure, appelé hypopion, n’identifie pas à lui seul la cause. Après une chirurgie ou une injection, douleur et baisse visuelle imposent notamment de rechercher une infection intraoculaire. Ne pas reprendre automatiquement un ancien corticoïde dans ce contexte.',
'Retirer les lentilles de contact devant un œil rouge douloureux et faire rechercher une kératite. Prévoir un transport adapté si la vision est altérée. Les urgences rétiniennes et neurologiques restent dans le tri du cours général.'),(4,44,57,60))
l.add('L’{anamnèse} recherche le rythme des épisodes et les indices étiologiques. Les symptômes extraoculaires peuvent orienter le bilan. Les médicaments déjà utilisés sont aussi importants que les maladies connues.',steps('Préciser début, douleur, photophobie, baisse visuelle et latéralité.','Rechercher récidives, atteinte de l’autre œil et comptes rendus antérieurs.','Noter chirurgie, injection, traumatisme, lentilles et épisodes herpétiques ou de zona.','Rechercher symptômes articulaires, digestifs, cutanés, respiratoires et autres éléments systémiques pertinents.','Recenser immunosuppression, infections connues et expositions selon le contexte, sans présumer une cause sur un seul élément.','Documenter collyres, traitements généraux, allergies, grossesse ou allaitement et antécédents de hausse de pression sous corticoïde.'),(55,56,57,58,60,61))
l.add('L’{examen ophtalmologique} confirme l’inflammation et en précise l’étendue. Il associe acuité, lampe à fente, pression et fond d’œil. Une acuité encore bonne ne suffit pas à écarter une atteinte active.',paras('Examiner les deux yeux. À la lampe à fente, rechercher cellules inflammatoires, précipités rétrocornéens, synéchies et atteinte cornéenne. L’état de la cornée importe avant une corticothérapie locale.',
'Mesurer la pression et interpréter une anomalie avec l’inflammation, l’anatomie et les traitements. Une hyperpression peut compliquer l’évolution ; le traitement corticoïde peut aussi y contribuer. Un résultat initial normal ne dispense pas du suivi.',
'Le fond d’œil recherche une atteinte postérieure et les complications. La dilatation est décidée après évaluation des contre-indications. Une autre cause de baisse visuelle peut coexister.'),(55,58,59,60,61))
l.add('L’{approche syndromique} distingue une inflammation antérieure isolée d’une atteinte plus étendue ou d’une autre urgence. La rougeur n’est pas un diagnostic. Un schéma thérapeutique dépend de cette distinction.',table(['Tableau','Question prioritaire','Conséquence'],[
['Œil rouge douloureux et photophobie','Cornée, uvée ou fermeture de l’angle ?','Examen urgent avant traitement spécifique.'],
['Cellules inflammatoires en chambre antérieure','Atteinte antérieure isolée ou extension ?','Caractériser l’inflammation et examiner le fond d’œil.'],
['Baisse avec corps flottants','Existe-t-il une atteinte du vitré ou de la rétine ?','Ne pas limiter le bilan au segment antérieur.'],
['Inflammation après geste oculaire','Complication infectieuse ?','Prise en charge urgente, sans corticoïde empirique isolé.'],
['Récidive ou manifestations générales','Cause infectieuse, inflammatoire ou médicamenteuse ?','Bilan dirigé et collaboration spécialisée.']
]),(55,56,57,58))
l.add('Le diagnostic positif repose sur une {inflammation antérieure objectivée}. La lampe à fente est déterminante. La recherche de la cause est une étape distincte qui conditionne les soins.',paras('Les symptômes orientent mais ne remplacent pas l’examen. Le spécialiste documente les cellules, les autres signes inflammatoires, la pression et les complications. L’évolution de ces éléments guide l’adaptation du traitement.',
'Une amélioration après corticoïde ne prouve pas une cause non infectieuse. L’effet anti-inflammatoire peut masquer des signes infectieux. Une évolution atypique, une aggravation ou une résistance impose une réévaluation.'),(55,58,60))
l.add('Les {examens complémentaires} répondent à des questions précises. Le bilan étiologique dépend du tableau, du terrain et des récidives. Une batterie identique de tests pour tous les patients n’est pas déduite des sources consultées.',
'<h3>9.a — Référence diagnostique</h3>'+paras('L’examen à la lampe à fente objective l’atteinte antérieure. Il s’intègre à l’examen complet, avec acuité, pression et fond d’œil. Aucun bilan sanguin isolé ne remplace cette étape.')+
'<h3>9.b — Première intention</h3>'+paras('Décrire localisation, côté, ancienneté et complications. Rechercher les éléments cliniques qui orientent vers une infection ou une maladie générale. Les résultats antérieurs évitent de répéter sans raison des explorations déjà contributives.')+
'<h3>9.c — Examens dirigés</h3>'+paras('Analyses sanguines et imagerie répondent à l’hypothèse étiologique. Une ponction de chambre antérieure peut être proposée par le spécialiste dans certaines situations incertaines ou infectieuses. Elle n’est pas présentée comme un examen systématique de toute première poussée.')+
'<h3>9.d — Seconde intention</h3>'+paras('La tomographie par cohérence optique (OCT) peut rechercher un œdème maculaire ou expliquer une baisse persistante. D’autres examens, dont une angiographie, sont choisis selon l’extension. Réévaluer une discordance entre amélioration antérieure et vision toujours diminuée.'),(55,56,58,59))
l.add('L’{arbre décisionnel} commence par l’examen urgent et l’évaluation de la cornée. La cause et l’étendue déterminent ensuite le traitement. Le suivi vérifie l’activité et la tolérance, pas seulement le soulagement.',steps('Si uvéite suspectée, alors contacter l’ophtalmologie en urgence.','Si infection ou complication après geste possible, alors organiser le bilan et le traitement causal adaptés.','Si inflammation antérieure non infectieuse confirmée, alors choisir un traitement local après vérification des contre-indications.','Si prévention ou traitement de synéchies nécessaire, alors discuter un cycloplégique adapté au terrain.','Si atteinte étendue, récidivante ou insuffisamment contrôlée, alors coordonner le bilan et l’escalade spécialisée.','À chaque contrôle, réévaluer vision, inflammation, pression et effets indésirables avant de réduire ou prolonger.'),(55,57,58,60,61))
l.add('La {prise en charge suisse} vise à maîtriser l’inflammation et à préserver la vision. Elle traite aussi une cause identifiée. Les collyres documentés ont des indications et des restrictions propres.',
'<h3>11.A — But</h3>'+paras('Obtenir le contrôle de l’inflammation, prévenir les synéchies et les autres complications, puis maintenir une vision utile. Une réduction de rougeur n’est pas à elle seule un objectif de suivi suffisant.')+
'<h3>11.B — Moyens</h3>'+paras('Un corticoïde local peut être retenu pour une inflammation antérieure non infectieuse après examen. Présentation suisse documentée : ')+dex+paras('Un traitement cycloplégique peut être choisi pour les synéchies et les symptômes selon l’évaluation. Présentation et restrictions distinctes : ')+atr+
paras('Ces fenêtres ne prescrivent pas une association automatique. Le glaucome figure parmi les contre-indications des deux notices. Une cornée lésée ou une infection exige une stratégie spécifique. En cas d’antécédent herpétique, les précautions du corticoïde ne se résument pas à une surveillance de la douleur.',
'Une infection identifiée demande un traitement anti-infectieux adapté. Aucune dose antivirale, antibiotique ou antituberculeuse n’est improvisée ici. Les formes complexes peuvent nécessiter des traitements systémiques ou une épargne cortisonique, décidés avec les spécialistes concernés.',
'La chirurgie traite certaines complications et n’est pas le traitement initial universel d’une uvéite antérieure. La sélection d’un traitement tient compte de l’âge, de la sévérité, de la cause et de la tolérance.')+
'<h3>11.C — Surveillance</h3>'+paras('Contrôler l’acuité, les signes inflammatoires et la pression de façon adaptée à l’activité et au produit. Rechercher infection, cataracte, atteinte cornéenne ou œdème maculaire si l’évolution l’évoque. Une douleur ou une baisse nouvelle nécessite un avis rapide.',
'Vérifier la technique d’instillation, l’œil traité et le calendrier. Le rythme horaire prévu par une notice dans les cas sévères relève d’une prescription et d’une surveillance ; il ne doit pas être prolongé par le patient sans réévaluation. Donner un plan de réduction explicite lorsque cette réduction est indiquée.',
'Pour Dexafree, respecter l’intervalle de 15 minutes entre collyres mentionné dans la notice. Jeter l’unidose utilisée et distinguer sa durée d’utilisation de celle du sachet. L’association avec un mydriatique renforce la nécessité du contrôle de pression.')+
'<h3>11.D — Pronostic et suivi</h3>'+paras('Le pronostic dépend de la cause, de l’étendue, des complications et de la réponse. Des rechutes sont possibles et justifient un nouveau contact plutôt qu’une réutilisation autonome d’anciens flacons.',
'Maintenir la collaboration avec les spécialistes d’une maladie générale lorsqu’elle est présente. Une amélioration n’annule pas les contrôles prévus. Chez l’enfant peu symptomatique, le suivi ne peut pas reposer sur la seule expression d’une douleur.'),(55,56,58,59,60,61))
l.add('La {prévention des complications} repose sur l’observance et la surveillance. Il n’existe pas de conseil unique empêchant toutes les causes d’uvéite. L’éducation doit préciser quoi faire devant une récidive ou un effet indésirable.',paras('Fournir les noms, concentrations, horaires, œil à traiter et modalités de réduction. Vérifier la compréhension du patient ou de l’aidant. La conservation des doses intactes et le rejet d’une unidose entamée sont deux règles différentes.',
'Signaler les troubles de conduite et l’effet prolongé de l’atropine. Prévenir les ingestions accidentelles, particulièrement chez l’enfant. Une rougeur de la face, une tachycardie, une fièvre ou une confusion après atropine doit faire demander une aide médicale.',
'Le traitement de la maladie causale et le suivi peuvent limiter les récidives ou leurs conséquences. Ne pas partager les collyres et ne pas transformer une ancienne ordonnance en automédication pour tout œil rouge.'),(55,56,60,61))
l.add('Les {points clés} relient inflammation, cause et suivi. L’examen spécialisé précède la prescription spécifique. L’absence de douleur et l’amélioration subjective ne suffisent pas à certifier la disparition de l’activité.',steps('Reconnaître douleur, photophobie et baisse visuelle comme des signes nécessitant un avis urgent.','Objectiver l’inflammation et rechercher une extension postérieure.','Distinguer cause infectieuse et non infectieuse avant de choisir le traitement.','Vérifier cornée, pression et contre-indications des produits retenus.','Prévenir les synéchies lorsque cela est indiqué sans généraliser l’atropine.','Surveiller aussi les effets systémiques des collyres.','Adapter la réduction au contrôle clinique et organiser le suivi.'),(55,56,57,58,60,61))
l.quiz([
('Question 1 — Une rougeur suffit-elle à diagnostiquer une uvéite antérieure ?', 'Non. Il faut objectiver l’inflammation, notamment à la lampe à fente.'),
('Question 2 — Une suspicion d’uvéite peut-elle attendre une consultation de routine ?', 'Non. La stratégie HUG demande de contacter l’ophtalmologue en urgence.'),
('Question 3 — Une amélioration sous corticoïde prouve-t-elle une cause non infectieuse ?', 'Non. L’action anti-inflammatoire peut masquer une infection.'),
('Question 4 — Une inflammation antérieure dispense-t-elle du fond d’œil ?', 'Non. Une extension postérieure ou une complication doit être recherchée.'),
('Question 5 — Qu’appelle-t-on synéchies postérieures ?', 'Des adhérences entre l’iris et le cristallin ; elles peuvent notamment déformer la pupille.'),
('Question 6 — Le bilan étiologique est-il identique pour tous ?', 'Non. Il est guidé par le tableau, les récidives, le terrain et les signes associés.'),
('Question 7 — Dexafree UD 0,1 % peut-il être commencé pour tout œil rouge ?', 'Non. Il nécessite un examen spécialisé, une indication et la vérification des contre-indications.'),
('Question 8 — Sa notice autorise-t-elle automatiquement un traitement prolongé au-delà de 14 jours ?', 'Non. Elle annonce généralement quelques jours à 14 jours au maximum. Une persistance exige une nouvelle décision documentée.'),
('Question 9 — Le glaucome est-il une simple précaution négligeable dans ces deux notices ?', 'Non. Il figure parmi leurs contre-indications et impose une décision thérapeutique adaptée.'),
('Question 10 — Une unidose ouverte peut-elle être gardée jusqu’à la fin du sachet ?', 'Non. Les règles de conservation des doses intactes ne permettent pas de réutiliser une unidose entamée.'),
('Question 11 — Les règles d’allaitement sont-elles identiques pour Dexafree et Atropine SDU Faure ?', 'Non. Dexafree peut être administré selon sa notice, tandis que celle de l’atropine demande d’interrompre l’allaitement si le traitement est indiqué.'),
('Question 12 — Un collyre d’atropine est-il dépourvu de risque systémique chez l’enfant ?', 'Non. Une toxicité peut survenir, y compris à dose thérapeutique ; la surveillance et l’occlusion lacrymale sont importantes.'),
('Question 13 — La dernière dose d’atropine permet-elle de reprendre immédiatement la conduite ?', 'Non. La notice interdit la conduite pendant le traitement et les quelques jours qui suivent.'),
('Question 14 — L’absence de douleur suffit-elle à arrêter les contrôles ?', 'Non. Des formes peu symptomatiques et des complications existent. Le suivi repose sur l’examen et la vision.')
],(55,56,57,58,60,61))
l.write()
